package org.usbworkbench;
import java.io.*;import java.util.*;import java.nio.*;import java.nio.charset.*;
/** Validated native archive manifests and bounded streaming extraction. No archive paths reach the OS. */
public final class ArchiveTools {
 public static final long MAX=16L*1024*1024*1024;public static final int MAX_MANIFEST=16*1024*1024;
 public static final class Entry{public final int index;public final String path;public final long size;public final boolean directory,special;Entry(int i,String p,long s,boolean d,boolean x){index=i;path=p;size=s;directory=d;special=x;}public String output(){return String.format(Locale.ROOT,"entry%05d.bin",index);}}
 public static final class Manifest{public final List<Entry> entries;public final long total,limit;public final String sourceHash,engine;Manifest(List<Entry> e,long n,long l,String hash){this(e,n,l,hash,null);}Manifest(List<Entry> e,long n,long l,String hash,String kind){engine=kind;entries=Collections.unmodifiableList(e);total=n;limit=l;sourceHash=hash;}}
 /** Small manifest only; never stores archive content. */
 public static final class MemoryFile implements WimFiles.RandomFile{private byte[] bytes=new byte[4096];private int length;public long size(){return length;}public int read(long at,byte[] b){if(at<0||at>=length)return 0;int n=(int)Math.min(b.length,length-at);System.arraycopy(bytes,(int)at,b,0,n);return n;}public void write(long at,byte[] b)throws IOException{if(at<0||at>MAX_MANIFEST||b.length>MAX_MANIFEST-at)throw new IOException("ARCHIVE_LIMIT");int end=(int)at+b.length;if(end>bytes.length)bytes=Arrays.copyOf(bytes,Math.min(MAX_MANIFEST,Math.max(end,bytes.length*2)));System.arraycopy(b,0,bytes,(int)at,b.length);length=Math.max(length,end);}public void truncate(long n)throws IOException{if(n!=0)throw new IOException("ARCHIVE_LIMIT");length=0;}public void sync(){}public void close(){}public byte[] data(){return Arrays.copyOf(bytes,length);}}
 public static Manifest decode(byte[] bytes,long limit,String hash)throws IOException{
  if(limit<1||limit>MAX||bytes.length<8||bytes.length>MAX_MANIFEST||!new String(bytes,0,8,StandardCharsets.US_ASCII).equals("UWARCH01"))throw new IOException("ARCHIVE_MANIFEST");
  List<Entry> list=new ArrayList<>();Map<String,Boolean> names=new HashMap<>();long total=0;int at=8;
  while(at<bytes.length){if(bytes.length-at<13||list.size()>=10000)throw new IOException("ARCHIVE_LIMIT");int type=bytes[at]&255;long count=u32(bytes,at+1),size=u64(bytes,at+5);at+=13;if((type!=1&&type!=2&&type!=3)||count<1||count>1024||count>bytes.length-at||size>limit-total||type!=2&&size!=0)throw new IOException("ARCHIVE_MANIFEST");String raw;
   try{raw=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes,at,(int)count)).toString();}catch(CharacterCodingException e){throw new IOException("ARCHIVE_PATH",e);}at+=(int)count;
   String path;try{path=ZipTools.safePath(raw);}catch(IOException e){throw new IOException("ARCHIVE_PATH",e);}String key=path.toLowerCase(Locale.ROOT);if(names.put(key,type==1)!=null)throw new IOException("ARCHIVE_PATH");list.add(new Entry(list.size(),path,size,type==1,type==3));total+=size;
  }
  for(Entry e:list){String parent=e.path;for(int slash=parent.lastIndexOf('/');slash>=0;slash=parent.lastIndexOf('/')){parent=parent.substring(0,slash);if(Boolean.FALSE.equals(names.get(parent.toLowerCase(Locale.ROOT))))throw new IOException("ARCHIVE_PATH");}}
  return new Manifest(list,total,limit,hash);
 }
 private static long u32(byte[] b,int at){long n=0;for(int i=0;i<4;i++)n|=(long)(b[at+i]&255)<<(8*i);return n;}
 private static long u64(byte[] b,int at)throws IOException{long n=0;for(int i=0;i<8;i++)n|=(long)(b[at+i]&255)<<(8*i);if(n<0)throw new IOException("ARCHIVE_LIMIT");return n;}
 public static String hash(OpticalImage.Source source,DiskTools.Progress p,ArchiveProcess.Cancelled cancel)throws IOException{
  try{java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");byte[] b=new byte[1048576];for(long at=0;at<source.size();){if(cancel.get())throw new IOException("CANCELLED");p.update(at,source.size());int n=(int)Math.min(b.length,source.size()-at);source.read(at,b,0,n);digest.update(b,0,n);at+=n;}p.update(source.size(),source.size());StringBuilder out=new StringBuilder();for(byte v:digest.digest())out.append(String.format(Locale.ROOT,"%02x",v&255));return out.toString();}catch(java.security.NoSuchAlgorithmException e){throw new IOException(e);}
 }
 public static UsbAnalyzer.Space statistics(File libs,OpticalImage.Source source,DiskTools.Progress p,ArchiveProcess.Cancelled cancel)throws IOException{
  MemoryFile memory=new MemoryFile();try(ArchiveFiles files=new ArchiveFiles(source,new WimFiles.Store(){public WimFiles.RandomFile create(String n)throws IOException{if(!n.equals("manifest.bin"))throw new IOException("FILE_PATH");return memory;}public void capacity(long n){}},Collections.singletonMap("manifest.bin",1064L))){ArchiveProcess.filesystem(libs,Arrays.asList("stats","1"),files,p,cancel,"ntfs");}
  byte[] b=memory.data();if(b.length<40||b.length>1064||!new String(b,0,8,StandardCharsets.US_ASCII).equals("UWFSTAT2")||u32(b,32)!=b.length-40)throw new IOException("ANALYZER_METADATA");long count=u64(b,8),free=u64(b,16),size=u64(b,24);if(size<512||size>2097152||count<1||free>count||count>source.size()/size)throw new IOException("ANALYZER_METADATA");String label;try{label=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b,40,b.length-40)).toString();}catch(CharacterCodingException e){throw new IOException("ANALYZER_METADATA",e);}return new UsbAnalyzer.Space(count*size,free*size,label,(int)u32(b,36));
 }
 public static Manifest scan(File libs,OpticalImage.Source source,long limit,DiskTools.Progress p,ArchiveProcess.Cancelled cancel)throws IOException{return scan(libs,source,limit,p,cancel,null,true);}
 public static Manifest scanFilesystem(File libs,OpticalImage.Source source,long limit,DiskTools.Progress p,ArchiveProcess.Cancelled cancel,String kind)throws IOException{if(!kind.equals("ntfs")&&!kind.equals("ext"))throw new IOException("FS_UNSUPPORTED");return scan(libs,source,limit,p,cancel,kind,true);}
 public static Manifest scanFilesystem(File libs,OpticalImage.Source source,long limit,DiskTools.Progress p,ArchiveProcess.Cancelled cancel,String kind,boolean fingerprint)throws IOException{if(!kind.equals("ntfs")&&!kind.equals("ext"))throw new IOException("FS_UNSUPPORTED");return scan(libs,source,limit,p,cancel,kind,fingerprint);}
 public static Manifest scanWim(File libs,OpticalImage.Source source,int index,String root,long limit,DiskTools.Progress p,ArchiveProcess.Cancelled cancel)throws IOException{if(index<1||index>256)throw new IOException("WIM_INDEX");String path=WimPaths.normalize(root,true);return scan(libs,source,limit,p,cancel,"wim:"+index+":"+path,true);}
 private static String process(File libs,List<String> args,ArchiveFiles files,DiskTools.Progress p,ArchiveProcess.Cancelled cancel,String kind,String password)throws IOException{if(kind!=null&&kind.startsWith("wim:")){String[] options=kind.split(":",3);List<String> command=new ArrayList<>();command.add(args.get(0).equals("list")?"usbwb-tree-list":"usbwb-tree-all");command.add(options[1]);command.add(args.get(1));command.add(options[2]);return WimProcess.run(libs,command,files,p,cancel::get);}return kind==null?ArchiveProcess.password(libs,args,files,p,cancel,password):ArchiveProcess.filesystem(libs,args,files,p,cancel,kind);}
 public static Manifest scanPassword(File libs,OpticalImage.Source source,long limit,DiskTools.Progress p,ArchiveProcess.Cancelled cancel,String password)throws IOException{return scan(libs,source,limit,p,cancel,null,true,password);}
 private static Manifest scan(File libs,OpticalImage.Source source,long limit,DiskTools.Progress p,ArchiveProcess.Cancelled cancel,String kind,boolean fingerprint)throws IOException{return scan(libs,source,limit,p,cancel,kind,fingerprint,"");}
 private static Manifest scan(File libs,OpticalImage.Source source,long limit,DiskTools.Progress p,ArchiveProcess.Cancelled cancel,String kind,boolean fingerprint,String password)throws IOException{
  if(limit<1||limit>MAX||source.size()<1||source.size()>64L*1024*1024*1024)throw new IOException("ARCHIVE_LIMIT");String hash=fingerprint?hash(source,p,cancel):"";MemoryFile memory=new MemoryFile();
  try(ArchiveFiles files=new ArchiveFiles(source,new WimFiles.Store(){public WimFiles.RandomFile create(String n)throws IOException{if(!n.equals("manifest.bin"))throw new IOException("FILE_PATH");return memory;}public void capacity(long n){}},Collections.singletonMap("manifest.bin",(long)MAX_MANIFEST))){process(libs,Arrays.asList("list",Long.toString(limit)),files,p,cancel,kind,password);Manifest m=decode(memory.data(),limit,hash);return new Manifest(m.entries,m.total,m.limit,m.sourceHash,kind);}
 }
 public static Map<String,String> extract(File libs,OpticalImage.Source source,Manifest m,WimFiles.Store store,DiskTools.Progress p,ArchiveProcess.Cancelled cancel)throws IOException{return extractPassword(libs,source,m,store,p,cancel,"");}
 public static Map<String,String> extractPassword(File libs,OpticalImage.Source source,Manifest m,WimFiles.Store store,DiskTools.Progress p,ArchiveProcess.Cancelled cancel,String password)throws IOException{
  Map<String,Long> sizes=new HashMap<>();for(Entry e:m.entries)if(!e.directory&&!e.special)sizes.put(e.output(),e.size);
  MemoryFile metadata=new MemoryFile();WimFiles.Store actual=store;if(m.engine!=null){sizes.put("manifest.bin",(long)MAX_MANIFEST);actual=new ArchiveFiles.NamedStore(){public WimFiles.RandomFile create(String name)throws IOException{return name.equals("manifest.bin")?metadata:store.create(name);}public void capacity(long n)throws IOException{store.capacity(n);}public void capacity(String name,long n)throws IOException{if(!name.equals("manifest.bin"))store.capacity(n);}};}
  Map<String,String> hashes;try(ArchiveFiles files=new ArchiveFiles(source,actual,sizes)){process(libs,Arrays.asList("all",Long.toString(m.limit)),files,p,cancel,m.engine,password);Map<String,Long> outputs=files.outputs();Map<String,Long> expected=new HashMap<>(sizes);if(m.engine!=null){outputs.remove("manifest.bin");expected.remove("manifest.bin");}if(!outputs.equals(expected))throw new IOException("ARCHIVE_CHANGED");hashes=files.hashes();hashes.remove("manifest.bin");}
  if(m.engine!=null){Manifest after=decode(metadata.data(),m.limit,m.sourceHash);if(after.entries.size()!=m.entries.size())throw new IOException("ARCHIVE_CHANGED");for(int i=0;i<m.entries.size();i++){Entry a=m.entries.get(i),b=after.entries.get(i);if(!a.path.equals(b.path)||a.size!=b.size||a.directory!=b.directory||a.special!=b.special)throw new IOException("ARCHIVE_CHANGED");}}
  if(!m.sourceHash.isEmpty()&&!hash(source,p,cancel).equals(m.sourceHash))throw new IOException("ARCHIVE_CHANGED");return hashes;
 }
 public static String listing(Manifest m){StringBuilder out=new StringBuilder(m.engine==null?"ARCHIVE_LIST\n":m.engine.startsWith("wim:")?"WIMTREE_LIST\n":"FSIMAGE_LIST\n");int count=0;for(Entry e:m.entries){if(count++==200){out.append("ARCHIVE_MORE ").append(m.entries.size()-200).append("\n");break;}out.append(e.special?"S ":e.directory?"D ":"F ").append(e.path).append(e.directory?"/":" • "+e.size+" B").append('\n');}return out.toString();}
}
